def _format_t(path, root=T):
    if not path:
        return {T: 'T', S: 'S', A: 'A'}.get(root, 'T')
    root_str = {T: 'T', S: 'S', A: 'A'}.get(root, 'T')
    parts = [root_str]
    i = 0
    while i < len(path):
        op = path[i]
        arg = path[i + 1]
        i += 2
        if op == '.':
            parts.append('.' + arg)
        elif op == '[':
            if type(arg) is slice:
                parts.append('[' + _format_slice(arg) + ']')
            elif type(arg) is tuple and all(type(x) is slice for x in arg):
                parts.append('[' + ', '.join(_format_slice(x) for x in arg) + ']')
            else:
                parts.append('[' + bbrepr(arg) + ']')
        elif op == 'P':
            parts.append('[' + bbrepr(arg) + ']')
        elif op == '(':
            args, kwargs = arg
            arg_strs = [bbrepr(a) for a in args]
            kwarg_strs = [f'{k}={bbrepr(v)}' for k, v in kwargs.items()]
            all_args = ', '.join(arg_strs + kwarg_strs)
            parts.append('(' + all_args + ')')
        elif op == 'x':
            parts.append('.__star__()')
        elif op == 'X':
            parts.append('.__starstar__()')
        elif op in ('+', '-', '*', '/', '%', ':', '&', '|', '^', '#'):
            op_map = {'+': '+', '-': '-', '*': '*', '/': '/', '%': '%', ':': '**', '&': '&', '|': '|', '^': '^', '#': '//'}
            sym = op_map[op]
            arg_repr = bbrepr(arg)
            rhs = arg_repr
            parts.append(' ' + sym + ' ' + rhs)
        elif op == '~':
            parts.insert(0, '~')
        elif op == '_':
            parts.insert(0, '-')
    return ''.join(parts)
