            raise err
        return default
    except GlomError as e:
        if default is not _MISSING:
            return default
        e._finalize(scope)
        if glom_debug:
            raise
        raise
    except Exception as e:
        if default is not _MISSING and isinstance(e, skip_exc):
            return default
        raise
